d={}
def fallback():
    print('default')
    return 7
try: d.get([],fallback())
except TypeError: print('unhashable')
print(d)

d={}
def argument():
    print('argument')
    return 'x'
try: d.get(key=argument())
except TypeError: print('keyword')
try: d.get('x',default=7)
except TypeError: print('keyword')
print(d)

d={'x':7}
method=d.get
for target in [method,dict.get.__get__(d,dict)]:
    try: target(**{'key':'x'})
    except TypeError: print('keyword')
try: dict.get(d,'x',default=9)
except TypeError: print('keyword')
print(method('x'),dict.get(d,'x'))

d={}
try: [d.get(key='x') for i in range(1)]
except TypeError: print('keyword')
try: d.get()
except TypeError: print('missing')
try: d.get(1,2,3)
except TypeError: print('extra')

d={'x':1}
def fallback():
    d['x']=9
    return 7
print(d.get('x',fallback()))

d={'x':7}
old=d
def argument():
    global d
    d={'x':99}
    return 'x'
print(d.get(argument(),0),d.get('x'),old)

class C:
    def __getattribute__(self,name):
        print('lookup',name)
        return lambda key,default: (key,default)
def argument(value):
    print('argument',value)
    return value
print(C().get(argument(1),argument(2)))

